    // Re-render on the server when another widget reports a change, and swap in the new values.
    function refresh() {
      if (!document.body.contains(root)) { return; }
      fetch(url).then(function (response) { return response.text(); }).then(function (text) {
        var fresh = new DOMParser().parseFromString(text, 'text/html').querySelector('[data-role="summary"]');
        var current = root.querySelector('[data-role="summary"]');
        if (fresh && current) { current.innerHTML = fresh.innerHTML; }
      }).catch(function () {});
    }
    if (window.__notesSummaryListener) {
      window.removeEventListener('notes:changed', window.__notesSummaryListener);
    }
    window.__notesSummaryListener = refresh;
    window.addEventListener('notes:changed', refresh);
  })();
</script>
